pub fn ter(op: &str, a: u128, b: u128, c: u128) -> Option<u128> {
    Some(match op {
        "i8x16.shuffle" => i8x16_shuffle(a, b, c),
        "v128.bitselect" => v128_bitselect(a, b, c),
        _ => return None,
    })
}

