pub fn sh(op: &str, a: u128, s: i32) -> Option<u128> {
    Some(match op {
        "i16x8.shl" => i16x8_shl(a, s),
        "i16x8.shr_s" => i16x8_shr_s(a, s),
        "i16x8.shr_u" => i16x8_shr_u(a, s),
        "i32x4.shl" => i32x4_shl(a, s),
        "i32x4.shr_s" => i32x4_shr_s(a, s),
        "i32x4.shr_u" => i32x4_shr_u(a, s),
        "i64x2.shl" => i64x2_shl(a, s),
        "i64x2.shr_s" => i64x2_shr_s(a, s),
        "i64x2.shr_u" => i64x2_shr_u(a, s),
        "i8x16.shl" => i8x16_shl(a, s),
        "i8x16.shr_s" => i8x16_shr_s(a, s),
        "i8x16.shr_u" => i8x16_shr_u(a, s),
        _ => return None,
    })
}

/// `replace_lane`: `value` is the raw bits of the lane-typed operand.
pub fn rep(op: &str, a: u128, lane: u32, value: u64) -> Option<u128> {
    Some(match op {
        "f32x4.replace_lane" => f32x4_replace_lane(a, lane, f32::from_bits(value as u32)),
        "f64x2.replace_lane" => f64x2_replace_lane(a, lane, f64::from_bits(value)),
        "i16x8.replace_lane" => i16x8_replace_lane(a, lane, value as i16),
        "i32x4.replace_lane" => i32x4_replace_lane(a, lane, value as i32),
        "i64x2.replace_lane" => i64x2_replace_lane(a, lane, value as i64),
        "i8x16.replace_lane" => i8x16_replace_lane(a, lane, value as i8),
        _ => return None,
    })
}

/// `splat`: `value` is the raw bits of the lane-typed operand.
pub fn spl(op: &str, value: u64) -> Option<u128> {
    Some(match op {
        "f32x4.splat" => f32x4_splat(f32::from_bits(value as u32)),
        "f64x2.splat" => f64x2_splat(f64::from_bits(value)),
        "i16x8.splat" => i16x8_splat(value as i16),
        "i32x4.splat" => i32x4_splat(value as i32),
        "i64x2.splat" => i64x2_splat(value as i64),
        "i8x16.splat" => i8x16_splat(value as i8),
        _ => return None,
    })
}

/// Scalar lane read, widened to raw `u64` bits.
pub fn ext(op: &str, a: u128, lane: u32) -> Option<u64> {
    Some(match op {
        "f32x4.extract_lane" => f32::to_bits(f32x4_extract_lane(a, lane)) as u64,
        "f64x2.extract_lane" => f64::to_bits(f64x2_extract_lane(a, lane)),
        "i16x8.extract_lane_s" => i16x8_extract_lane_s(a, lane) as i64 as u64,
        "i16x8.extract_lane_u" => i16x8_extract_lane_u(a, lane) as u64,
        "i32x4.extract_lane" => i32x4_extract_lane(a, lane) as i64 as u64,
        "i64x2.extract_lane" => i64x2_extract_lane(a, lane) as i64 as u64,
        "i8x16.extract_lane_s" => i8x16_extract_lane_s(a, lane) as i64 as u64,
        "i8x16.extract_lane_u" => i8x16_extract_lane_u(a, lane) as u64,
        _ => return None,
    })
}

pub fn tst(op: &str, a: u128) -> Option<i32> {
    Some(match op {
        "i16x8.all_true" => i16x8_all_true(a),
        "i16x8.bitmask" => i16x8_bitmask(a),
        "i32x4.all_true" => i32x4_all_true(a),
        "i32x4.bitmask" => i32x4_bitmask(a),
        "i64x2.all_true" => i64x2_all_true(a),
        "i64x2.bitmask" => i64x2_bitmask(a),
        "i8x16.all_true" => i8x16_all_true(a),
        "i8x16.bitmask" => i8x16_bitmask(a),
        "v128.any_true" => v128_any_true(a),
        _ => return None,
    })
}
